        let saved=null;try{saved=JSON.parse(localStorage.getItem(key)||'null');}catch(_){}
        const clamp=(left,top)=>{icon.style.left=Math.round(Math.max(4,Math.min(window.innerWidth-56,left)))+'px';icon.style.top=Math.round(Math.max(4,Math.min(window.innerHeight-56,top)))+'px';};
        clamp(Number(saved?.left)||Math.max(8,window.innerWidth-66),Number(saved?.top)||Math.max(8,window.innerHeight-70));
        let gesture=null;
        icon.addEventListener('pointerdown',e=>{if(e.button!==0)return;gesture={id:e.pointerId,x:e.clientX,y:e.clientY,left:parseFloat(icon.style.left),top:parseFloat(icon.style.top),moved:false};try{icon.setPointerCapture(e.pointerId);}catch(_){}e.preventDefault();});
        icon.addEventListener('pointermove',e=>{if(!gesture||gesture.id!==e.pointerId)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(Math.hypot(dx,dy)>5)gesture.moved=true;if(gesture.moved)clamp(gesture.left+dx,gesture.top+dy);});
        icon.addEventListener('pointerup',e=>{if(!gesture||gesture.id!==e.pointerId)return;const moved=gesture.moved;gesture=null;try{icon.releasePointerCapture(e.pointerId);}catch(_){};if(moved){try{localStorage.setItem(key,JSON.stringify({left:parseFloat(icon.style.left),top:parseFloat(icon.style.top)}));}catch(_){}}else restore();});
