        icon.addEventListener('click',e=>{if(e.detail===0)restore();});
        const onResize=()=>{if(icon.isConnected)clamp(parseFloat(icon.style.left),parseFloat(icon.style.top));};
        window.addEventListener('resize',onResize,{passive:true});
        icon.dispose=()=>{window.removeEventListener('resize',onResize);icon.remove();};
        document.body.append(icon);return icon;
