      const cleaned=paletteList.slice(0,MAX_PALETTES).map(p=>({name:String(p?.name||'Palette').slice(0,35),swatches:(Array.isArray(p?.swatches)?p.swatches:[]).slice(0,12).map(safeHex).filter(Boolean)})).filter(p=>p.swatches.length);
